SELECT (DATE_TRUNC('DAY', "REFRESH_START_AT")) AS "TIME_BUCKET", SUM(CASE WHEN NOT TARGET_LAG_SEC IS NULL AND ACTUAL_LAG_SEC > TARGET_LAG_SEC THEN 1 ELSE 0 END) AS "DQ_SLA_BREACH_COUNT" FROM (SELECT "QUALIFIED_NAME" AS QUALIFIED_NAME, "NAME" AS DYNAMIC_TABLE_NAME, "DATABASE_NAME" AS DATABASE_NAME, "SCHEMA_NAME" AS SCHEMA_NAME, "STATE" AS REFRESH_STATE, "STATE_MESSAGE" AS STATE_MESSAGE, "REFRESH_ACTION" AS REFRESH_ACTION, "REFRESH_TRIGGER" AS REFRESH_TRIGGER, "TARGET_LAG_SEC" AS TARGET_LAG_SEC, (TRY_TO_TIMESTAMP_NTZ("REFRESH_START_TIME")) AS REFRESH_START_AT, (TRY_TO_TIMESTAMP_NTZ("REFRESH_END_TIME")) AS REFRESH_END_AT, (TRY_TO_TIMESTAMP_NTZ("DATA_TIMESTAMP")) AS DATA_TIMESTAMP_AT, (DATEDIFF(SECOND, (TRY_TO_TIMESTAMP_NTZ("DATA_TIMESTAMP")), (TRY_TO_TIMESTAMP_NTZ("REFRESH_START_TIME")))) AS ACTUAL_LAG_SEC, (DATEDIFF(SECOND, (TRY_TO_TIMESTAMP_NTZ("REFRESH_START_TIME")), (TRY_TO_TIMESTAMP_NTZ("REFRESH_END_TIME")))) AS REFRESH_DURATION_SEC, (NULL) AS ACCOUNT_NAME /* The account these rows came from (see the ACCOUNT_OF shim). */ FROM dynamic_table_refresh_history) AS base GROUP BY (DATE_TRUNC('DAY', "REFRESH_START_AT")) ORDER BY "DQ_SLA_BREACH_COUNT" DESC NULLS LAST, "TIME_BUCKET" LIMIT 100
